import bpy,numpy as np,json,sys
from pathlib import Path
D=Path(__file__).resolve().parent;sys.path.insert(0,str(D));from aov_tools import attach,configure_files,read_outputs,statistics

def setup_iron_aovs(sc):
 out=D/'aov/edge_cut';out.mkdir(parents=True,exist_ok=True);o=sc.objects['Lab Chest Lower Rim'];o.data=o.data.copy();m=o.data.materials[0].copy();o.data.materials[0]=m;nt=m.node_tree;bare=nt.nodes['Exposed iron Filament diagnostic reflectance'];black=nt.nodes['Blackened conductive iron'];g=nt.nodes.new('ShaderNodeNewGeometry')
 signals=[('Iron_ExposedBlend','VALUE',nt.nodes['Localized exposed iron'].inputs[0]),('Iron_OxideCoverage','VALUE',nt.nodes['Opaque scale coverage'].inputs[0]),('Iron_RoughBare','VALUE',bare.inputs['Roughness']),('Iron_GeometryNormal','COLOR',g.outputs['True Normal']),('Iron_FinalNormal','COLOR',black.inputs['Normal']),('Iron_SurfaceAlpha','VALUE',black.inputs['Alpha'])];records,_=attach(sc,m,signals);names=[x[0] for x in signals];configure_files(sc,names,out);sc.render.resolution_x=1600;sc.render.resolution_y=800;sc.render.resolution_percentage=100;sc.render.use_border=True;sc.render.use_crop_to_border=True;sc.render.border_min_x=.23;sc.render.border_max_x=.81;sc.render.border_min_y=.20;sc.render.border_max_y=.68;sc.cycles.samples=32;sc.cycles.seed=17;sc.render.filepath=str(out/'beauty.png');sc.render.image_settings.file_format='PNG';sc.render.image_settings.color_mode='RGBA';(out/'signals.json').write_text(json.dumps(records,indent=2));bpy.ops.render.render(write_still=True);arrays=read_outputs(out,names);stats,scope=statistics(arrays,'Iron_SurfaceAlpha');np.savez_compressed(out/'passes.npz',**arrays);(out/'statistics.json').write_text(json.dumps(stats,indent=2));assert scope.sum()>100;assert all(np.isfinite(a).all() for a in arrays.values());print('EDGE AOVS VERIFIED',names,flush=True)
